      <div className="flex flex-wrap gap-1.5 mb-6">
        {project.tags.slice(0, 3).map(tag => (
          <span key={tag} className="px-1.5 py-0.5 rounded bg-white/5 text-[8px] text-slate-500 uppercase font-black whitespace-nowrap border border-white/5">
