const Projects: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [activeFilter, setActiveFilter] = useState<ProjectStatus | 'All'>('All');

  const filters: (ProjectStatus | 'All')[] = [
    'All',
    ProjectStatus.LIVE,
    ProjectStatus.PROTOTYPE,
    ProjectStatus.IN_PROGRESS,
  ];

  const filteredProjects = activeFilter === 'All' 
    ? PROJECTS 
    : PROJECTS.filter(p => p.status === activeFilter);

  useEffect(() => {
    if (selectedProject) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    return () => document.body.classList.remove('modal-open');
  }, [selectedProject]);

  return (
    <section id="projects" className="py-20 border-t border-white/5">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 mb-14">
        <div>
          <h2 className="text-3xl font-bold mb-3 tracking-tight">Projects</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em]">Select systems and experiments</p>
        </div>

        <div className="flex items-center gap-2 p-1.5 rounded-2xl bg-white/5 border border-white/5 self-start lg:self-center">
          {filters.map((f) => (
            <button
              key={f}
              onClick={() => setActiveFilter(f)}
              className={`px-5 py-2 rounded-xl text-[10px] font-bold uppercase tracking-wider transition-all ${
                activeFilter === f
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20'
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      <motion.div 
        layout
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
      >
        <AnimatePresence mode="popLayout">
          {filteredProjects.map((project) => (
            <ProjectCard 
              key={project.id} 
              project={project} 
              onOpen={setSelectedProject} 
            />
          ))}
        </AnimatePresence>
      </motion.div>

      <AnimatePresence mode="wait">
        {selectedProject && (
          <ProjectModal 
            key={`modal-${selectedProject.id}`}
            project={selectedProject} 
            onClose={() => setSelectedProject(null)} 
          />
        )}
      </AnimatePresence>
    </section>
  );
};

export default Projects;

